/** The ten planned pages, in publication order within each group. Codes are used in tables. */
const SERVICE_ORDER = ["manned-guarding", "cctv-installation", "electric-fencing", "events-security", "k9-unit", "alarm-response", "vip-close-protection"]
const LOCATION_ORDER = ["nairobi", "nakuru", "rongo"]
export const PAGES = [
  ...SERVICE_ORDER.map((id, i) => {
    const s = SERVICES.find((x) => x.id === id)
    const planned = PLANNED_PAGES.find((p) => p.kind === "service" && p.path === `/services/${id === "k9-unit" ? "k9-unit-services" : id}/`)
    return { code: `S${i + 1}`, kind: "service", key: id, name: s.name, path: planned.path, wave: i < 3 ? 1 : 2 }
  }),
  ...LOCATION_ORDER.map((slug, i) => {
    const p = PLANNED_PAGES.find((x) => x.path === `/locations/${slug}/`)
    return { code: `L${i + 1}`, kind: "location", key: slug, name: p.name, path: p.path, wave: i < 2 ? 1 : 2 }
  }),
]
export const ALL = PAGES.map((p) => p.code)
export const SVC = PAGES.filter((p) => p.kind === "service").map((p) => p.code)
export const LOC = PAGES.filter((p) => p.kind === "location").map((p) => p.code)
export const WAVE1 = PAGES.filter((p) => p.wave === 1).map((p) => p.code)
export const pageByCode = (code) => PAGES.find((p) => p.code === code)

/** Image files under public/, counted from disk so the register never states a stale number. */
function publicImages() {
  const out = { team: 0, other: 0 }
  const walk = (dir, inTeam) => {
    for (const name of readdirSync(dir)) {
      const full = path.join(dir, name)
      if (statSync(full).isDirectory()) walk(full, inTeam || name === "team")
      else if (/\.(jpe?g|png|webp)$/i.test(name)) out[inTeam ? "team" : "other"]++
    }
  }
  walk(path.join(ROOT, "public"), false)
  return out
}
export const PUBLIC_IMAGES = publicImages()

const mk = (o) => ({ conflict: "", refs: [], onFile: null, impactNote: "", ...o })

/** Priority is derived, never typed: it follows from what the item blocks and how many pages it affects. */
export function priorityOf(item) {
  const wave1 = item.pages.some((p) => WAVE1.includes(p))
  if (item.impact === "BLOCKS PUBLICATION") return item.pages.length >= 5 || wave1 ? "Critical" : "High"
  if (item.impact === "BLOCKS CLAIM") return item.pages.length >= 5 ? "High" : "Medium"
  if (item.impact === "BLOCKS SECTION") return "Medium"
  return "Low"
}

